import{_ as t,o as a,c as o,a3 as n}from"./chunks/framework.B9qR_F1m.js";const p=JSON.parse(`{"title":"Agent-Ready, Extensible Modules","description":"Feluqa's belief that agents should help users create and evolve product-specific software through explicit extension points.","frontmatter":{"sidebarTitle":"Agent Modules","icon":"blocks","title":"Agent-Ready, Extensible Modules","description":"Feluqa's belief that agents should help users create and evolve product-specific software through explicit extension points.","summary":"States Feluqa's belief that broad shared capabilities can be affordable while organisations shape the specialised depth of their Products. It describes extensible Modules and Features, explicit hooks and contracts for user-selected agents, CLI-assisted software generation and verification, and the intended cost and deployment benefits while marking the agent workflow as a target.","date":"2026-10-29T00:00:00.000Z","lastmod":"2026-10-29T00:00:00.000Z","weight":0,"status":"Target","tags":["feluqa","concepts","modules","agents","extensibility"],"draft":true,"author":{"name":"El Moumen Yassine","url":"https://numerimondes.com","linkedin":"https://www.linkedin.com/in/elmoumenyassine","email":"yassine@numerimondes.com"}},"headers":[],"relativePath":"get-started/agentic-development/agent-ready-extensible-modules.md","filePath":"get-started/agentic-development/agent-ready-extensible-modules.md"}`),i={name:"get-started/agentic-development/agent-ready-extensible-modules.md"};function s(r,e,d,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="agent-ready-extensible-modules" tabindex="-1">Agent-Ready, Extensible Modules <a class="header-anchor" href="#agent-ready-extensible-modules" aria-label="Permalink to &quot;Agent-Ready, Extensible Modules&quot;">​</a></h1><p>Feluqa&#39;s belief is that <strong>breadth is now affordable; depth belongs to users</strong>.</p><p>The platform should provide a broad, shared foundation, while each organisation shapes the specialised software its work requires.</p><h2 id="software-that-can-be-extended" tabindex="-1">Software that can be extended <a class="header-anchor" href="#software-that-can-be-extended" aria-label="Permalink to &quot;Software that can be extended&quot;">​</a></h2><p>Feluqa Modules and Features are intended to be extensible through explicit, documented contracts and hooks. Those extension points let a developer or an authorised AI agent create new capabilities for a Product without waiting for every organisation-specific workflow to become part of the Feluqa Platform.</p><p>An agent should be able to understand a project&#39;s schemas, module manifests, available capabilities, and extension points; propose or implement a Module or Feature; and help evolve it as business needs change. The resulting work should be ordinary, reviewable software with clear ownership, dependencies, permissions, and version history.</p><h2 id="agents-use-the-tools-the-developer-chooses" tabindex="-1">Agents use the tools the developer chooses <a class="header-anchor" href="#agents-use-the-tools-the-developer-chooses" aria-label="Permalink to &quot;Agents use the tools the developer chooses&quot;">​</a></h2><p>Feluqa is intended to work with local agents and with other agents chosen by the organisation. A local agent can work with business requirements, source, and data inside the organisation&#39;s controlled environment. If an organisation chooses an external agent, it controls that choice and the information made available to it; Feluqa does not assume that every agent is local or that every provider handles data in the same way.</p><p>The Feluqa CLI is intended to help agents use the same project workflow as developers: inspect the project, make changes through supported extension points, compile, validate, run tests and evaluations, package, and distribute the result. Machine-readable commands, declared capabilities, scoped agent identities, approval rules, and audit records are part of this direction.</p><h2 id="evolve-products-without-building-every-possibility-up-front" tabindex="-1">Evolve products without building every possibility up front <a class="header-anchor" href="#evolve-products-without-building-every-possibility-up-front" aria-label="Permalink to &quot;Evolve products without building every possibility up front&quot;">​</a></h2><p>Instead of implementing every specialised workflow in the Platform, Feluqa aims to let organisations add or refine product capabilities as needs arise. An agent can help make that change quickly, reducing the time and cost of adding specialised capabilities. Compilation, validation, review, and controlled distribution keep it part of the application&#39;s normal software lifecycle. This is the intended route to evolvable software, not a claim that arbitrary uncompiled code can be inserted into a running application.</p><h2 id="direction-and-current-status" tabindex="-1">Direction and current status <a class="header-anchor" href="#direction-and-current-status" aria-label="Permalink to &quot;Direction and current status&quot;">​</a></h2><p>Agent-ready extension contracts, agent identities, provider choice, and machine-driven build and distribution workflows are product direction. The Feluqa CLI, console, module contracts, and build-time tooling have some foundations, but the complete agent workflow, dynamic module lifecycle, and companion agent product are not implemented. See <a href="/get-started/agentic-development/complementary-agent-project">the complementary agent project</a> for the proposed relationship between Feluqa and a separate agent product.</p>',13)])])}const m=t(i,[["render",s]]);export{p as __pageData,m as default};
